    // Hero Section (Updated)
    'landing.hero.tagline': 'Your rights are real and enforceable. When tenants organize together, they win.',

    // Rights Section
    'landing.rights.title': 'Your Rights as a Nevada Tenant',
    'landing.rights.subtitle': 'Nevada law (NRS 118A) gives you concrete, enforceable rights. Here\'s what landlords must do.',
    'landing.rights.habitability.title': 'The Right to Habitable Housing',
    'landing.rights.habitability.weatherproof': 'Effective weatherproofing of roof, walls, windows, and doors',
    'landing.rights.habitability.plumbing': 'Functioning plumbing with hot and cold running water',
    'landing.rights.habitability.heat': 'Adequate heating and electrical systems in working order',
    'landing.rights.habitability.pest': 'Pest control keeping the building reasonably free from rodents and insects',
    'landing.rights.habitability.structure': 'Structural integrity with floors, walls, ceilings, and stairways in good repair',
    'landing.rights.habitability.nrs': 'NRS 118A.290 - Implied Warranty of Habitability',
    'landing.rights.retaliation.title': 'Protection Against Retaliation',
    'landing.rights.retaliation.description': 'Landlords cannot punish you for exercising your legal rights. It is illegal for them to retaliate against you for:',
    'landing.rights.retaliation.organize': 'Organizing or joining a tenant union',
    'landing.rights.retaliation.report': 'Reporting code violations to government agencies',
    'landing.rights.retaliation.union': 'Filing habitability-related lawsuits or complaints',
    'landing.rights.retaliation.nrs': 'NRS 118A.510 - Anti-Retaliation Protection. Violators can be forced to pay $2,500 in punitive damages plus actual damages.',
    'landing.rights.remedies.title': 'Your Remedies When Landlords Fail',
    'landing.rights.remedies.intro': 'If your landlord violates the habitability warranty, you have legal remedies:',
    'landing.rights.remedies.essential.title': 'For Essential Services (heat, water, electricity, locks)',
    'landing.rights.remedies.essential.text': 'Give written notice, wait 48 hours (excluding weekends), then you may obtain the service yourself and deduct actual costs from rent, or withhold rent until repairs are made.',
    'landing.rights.remedies.non_essential.title': 'For Other Habitability Issues (pests, structural damage)',
    'landing.rights.remedies.non_essential.text': 'Give written notice, wait 14 days for landlord to fix or make best efforts, then you may terminate the lease, withhold rent without late fees, or for repairs under $100, repair and deduct.',
    'landing.rights.remedies.warning.title': 'Important for Rent Withholding:',
    'landing.rights.remedies.warning.text': 'Nevada courts require you to deposit withheld rent in court escrow to use habitability as an eviction defense. Without this, you risk losing your case.',

    // Organizing Works Section
    'landing.organizing.title': 'Organizing Works—Here\'s the Proof',
    'landing.organizing.subtitle': 'Across the country, tenants who organize together win concrete improvements. These aren\'t isolated incidents but part of a growing national movement.',
    'landing.organizing.kc.title': 'KC Tenants Strike',
    'landing.organizing.kc.stat': '248 days on strike. $300,000 in back rent forgiven.',
    'landing.organizing.kc.win1': 'Rent freeze for all current tenants (second year capped at 5%)',
    'landing.organizing.kc.win2': 'Nearly $300,000 in withheld rent forgiven—$0 back rent owed',
    'landing.organizing.kc.win3': 'Formal union recognition with annual renegotiation rights',
    'landing.organizing.kc.win4': 'Anti-retaliation protections written into agreement, late fee reform, comprehensive repair guarantees',
    'landing.organizing.ny.title': 'New York Good Cause Eviction',
    'landing.organizing.ny.stat': '~1 million renters protected',
    'landing.organizing.ny.description': 'After five years of sustained organizing, New York passed statewide protections in 2024.',
    'landing.organizing.ny.win1': 'Caps presumptively unreasonable rent increases at 5% + CPI (or 10%, whichever is lower)',
    'landing.organizing.ny.win2': 'Requires landlords to have good cause to evict or refuse lease renewal',
    'landing.organizing.ca.title': 'California AB 1482',
    'landing.organizing.ca.stat': '~8 million renters gained protection',
    'landing.organizing.ca.description': 'California\'s Tenant Protection Act (2019) became a model for tenant protections nationwide.',
    'landing.organizing.ca.win1': 'Statewide rent increase limits of 5% + local CPI (or 10% max)',
    'landing.organizing.ca.win2': 'Just cause eviction requirements after 12 months + one month\'s relocation assistance',
    'landing.organizing.or.title': 'Oregon SB 608',
    'landing.organizing.or.stat': 'First statewide rent control in the nation',
    'landing.organizing.or.description': 'Oregon became the first state to pass statewide rent control (2019).',
    'landing.organizing.or.win1': 'Annual rent increase cap of 7% + CPI',
    'landing.organizing.or.win2': 'Just cause eviction protections after 12 months',
    'landing.organizing.message': 'Individual complaints get ignored. Collective action gets results. These victories prove it.',

    // Local Crisis Section
    'landing.crisis.title': 'The Housing Crisis in Reno-Sparks',
    'landing.crisis.subtitle': 'These aren\'t abstract problems—they\'re the conditions tenants in Washoe County face every month.',
    'landing.crisis.rent_increase': '40-45%',
    'landing.crisis.rent_increase_label': 'Rent increase since 2019',
    'landing.crisis.cost_burdened': 'Cost-burdened renters (pay 30%+ of income on housing)',
