    'landing.crisis.luxury_units': 'Of apartments built in Reno (last decade) are luxury units',
    'landing.crisis.impact': 'Rents are up 40-45% in five years. More than half of renters are cost-burdened. A minimum wage worker needs to work 82 hours per week to afford a one-bedroom apartment. Nevada has the fastest eviction process in the nation. Meanwhile, luxury apartments sit empty while 1,760 people have nowhere to sleep.',
    'landing.crisis.support_title': 'Support Exists If You Need It',
