    // Hero Section (Updated)
    'landing.hero.tagline': 'Tus derechos son reales y ejecutables. Cuando los inquilinos se organizan juntos, ganan.',

    // Rights Section
    'landing.rights.title': 'Tus Derechos como Inquilino de Nevada',
    'landing.rights.subtitle': 'La ley de Nevada (NRS 118A) te otorga derechos concretos y ejecutables. Esto es lo que los propietarios deben hacer.',
    'landing.rights.habitability.title': 'El Derecho a una Vivienda Habitable',
    'landing.rights.habitability.weatherproof': 'Impermeabilización efectiva del techo, paredes, ventanas y puertas',
    'landing.rights.habitability.plumbing': 'Tuberías funcionales con agua corriente caliente y fría',
    'landing.rights.habitability.heat': 'Sistemas de calefacción y electricidad adecuados en buen estado de funcionamiento',
    'landing.rights.habitability.pest': 'Control de plagas manteniendo el edificio razonablemente libre de roedores e insectos',
    'landing.rights.habitability.structure': 'Integridad estructural con pisos, paredes, techos y escaleras en buen estado de reparación',
    'landing.rights.habitability.nrs': 'NRS 118A.290 - Garantía Implícita de Habitabilidad',
    'landing.rights.retaliation.title': 'Protección Contra Represalias',
    'landing.rights.retaliation.description': 'Los propietarios no pueden castigarte por ejercer tus derechos legales. Es ilegal para ellos tomar represalias contra ti por:',
    'landing.rights.retaliation.organize': 'Organizarte o unirte a un sindicato de inquilinos',
    'landing.rights.retaliation.report': 'Reportar violaciones del código a agencias gubernamentales',
    'landing.rights.retaliation.union': 'Presentar demandas o quejas relacionadas con habitabilidad',
    'landing.rights.retaliation.nrs': 'NRS 118A.510 - Protección contra Represalias. Los infractores pueden ser obligados a pagar $2,500 en daños punitivos más daños reales.',
    'landing.rights.remedies.title': 'Tus Recursos Cuando los Propietarios Fallan',
    'landing.rights.remedies.intro': 'Si tu propietario viola la garantía de habitabilidad, tienes recursos legales:',
    'landing.rights.remedies.essential.title': 'Para Servicios Esenciales (calefacción, agua, electricidad, cerraduras)',
    'landing.rights.remedies.essential.text': 'Da aviso escrito, espera 48 horas (excluyendo fines de semana), luego puedes obtener el servicio tú mismo y deducir los costos reales del alquiler, o retener el alquiler hasta que se realicen las reparaciones.',
    'landing.rights.remedies.non_essential.title': 'Para Otros Problemas de Habitabilidad (plagas, daño estructural)',
    'landing.rights.remedies.non_essential.text': 'Da aviso escrito, espera 14 días para que el propietario repare o haga su mejor esfuerzo, luego puedes rescindir el contrato, retener el alquiler sin multas por mora, o para reparaciones menores a $100, repara y deduce.',
    'landing.rights.remedies.warning.title': 'Importante para Retención de Alquiler:',
    'landing.rights.remedies.warning.text': 'Los tribunales de Nevada requieren que deposites el alquiler retenido en depósito judicial para usar la habitabilidad como defensa de desalojo. Sin esto, corre el riesgo de perder tu caso.',

    // Organizing Works Section
    'landing.organizing.title': 'La Organización Funciona—Aquí está la Prueba',
    'landing.organizing.subtitle': 'En todo el país, los inquilinos que se organizan juntos ganan mejoras concretas. No son incidentes aislados sino parte de un movimiento nacional en crecimiento.',
    'landing.organizing.kc.title': 'Huelga de Inquilinos de KC',
    'landing.organizing.kc.stat': '248 días en huelga. $300,000 en alquiler atrasado perdonado.',
    'landing.organizing.kc.win1': 'Congelación de alquiler para todos los inquilinos actuales (segundo año limitado al 5%)',
    'landing.organizing.kc.win2': 'Casi $300,000 en alquiler retenido perdonado—$0 de alquiler atrasado adeudado',
    'landing.organizing.kc.win3': 'Reconocimiento formal del sindicato con derechos de renegociación anual',
    'landing.organizing.kc.win4': 'Protecciones contra represalias escritas en el acuerdo, reforma de tarifas por mora, garantías de reparación integral',
    'landing.organizing.ny.title': 'Nueva York Buena Causa de Desalojo',
    'landing.organizing.ny.stat': '~1 millón de inquilinos protegidos',
    'landing.organizing.ny.description': 'Después de cinco años de organización sostenida, Nueva York aprobó protecciones estatales en 2024.',
    'landing.organizing.ny.win1': 'Limita aumentos de alquiler presuntivamente irrazonables al 5% + IPC (o 10%, lo que sea menor)',
    'landing.organizing.ny.win2': 'Requiere que los propietarios tengan justa causa para desalojar o rechazar la renovación del contrato',
    'landing.organizing.ca.title': 'California AB 1482',
    'landing.organizing.ca.stat': '~8 millones de inquilinos ganaron protección',
    'landing.organizing.ca.description': 'La Ley de Protección de Inquilinos de California (2019) se convirtió en un modelo para protecciones de inquilinos en todo el país.',
    'landing.organizing.ca.win1': 'Límites de aumento de alquiler estatal del 5% + IPC local (o máximo 10%)',
    'landing.organizing.ca.win2': 'Requisitos de desalojo con justa causa después de 12 meses + asistencia de reubicación de un mes',
    'landing.organizing.or.title': 'Oregon SB 608',
    'landing.organizing.or.stat': 'Primer control de alquiler estatal de la nación',
    'landing.organizing.or.description': 'Oregon se convirtió en el primer estado en aprobar control de alquiler estatal (2019).',
    'landing.organizing.or.win1': 'Límite de aumento de alquiler anual del 7% + IPC',
    'landing.organizing.or.win2': 'Protecciones de desalojo con justa causa después de 12 meses',
    'landing.organizing.message': 'Las quejas individuales se ignoran. La acción colectiva produce resultados. Estas victorias lo prueban.',

    // Local Crisis Section
    'landing.crisis.title': 'La Crisis de Vivienda en Reno-Sparks',
    'landing.crisis.subtitle': 'No son problemas abstractos—son las condiciones que los inquilinos del Condado de Washoe enfrentan cada mes.',
    'landing.crisis.rent_increase': '40-45%',
    'landing.crisis.rent_increase_label': 'Aumento de alquiler desde 2019',
    'landing.crisis.cost_burdened': 'Inquilinos con carga de costos (pagan 30%+ de ingresos en vivienda)',
    'landing.crisis.minimum_wage_hours': 'Horas de salario mínimo por semana necesarias para pagar un apartamento de 1 dormitorio',
    'landing.crisis.homeless': 'Personas sin hogar en el Condado de Washoe (2024)',
    'landing.crisis.daily_evictions': 'Desalojos presentados por día (estatal)',
    'landing.crisis.luxury_units': 'De apartamentos construidos en Reno (última década) son unidades de lujo',
    'landing.crisis.impact': 'Los alquileres han subido 40-45% en cinco años. Más de la mitad de los inquilinos están con carga de costos. Un trabajador de salario mínimo necesita trabajar 82 horas por semana para pagar un apartamento de un dormitorio. Nevada tiene el proceso de desalojo más rápido de la nación. Mientras tanto, los apartamentos de lujo permanecen vacíos mientras 1,760 personas no tienen dónde dormir.',
    'landing.crisis.support_title': 'Apoyo Disponible Si Lo Necesitas',
    'landing.crisis.support_intro': 'No estás solo. Asistencia legal, asistencia de emergencia y apoyo organizativo están disponibles:',
