    // Hero Section (Updated)
    'landing.hero.tagline': 'Ang iyong mga karapatan ay tunay at maipapatupad. Kapag nagsama-sama ang mga tenant, nanalo sila.',

    // Rights Section
    'landing.rights.title': 'Ang Iyong Mga Karapatan Bilang Nevada Tenant',
    'landing.rights.subtitle': 'Ang Nevada law (NRS 118A) ay nagbibigay sa iyo ng konkretong, maipapatupad na mga karapatan. Ito ang dapat gawin ng mga landlord.',
    'landing.rights.habitability.title': 'Ang Karapatan sa Habitable Housing',
    'landing.rights.habitability.weatherproof': 'Epektibong proteksyon mula sa ulan ng bubong, dingding, bintana, at pintuan',
    'landing.rights.habitability.plumbing': 'Gumagana na tubo na may mainit at malamig na tumatakbo na tubig',
    'landing.rights.habitability.heat': 'Sapat na sistema ng pag-init at kuryente na nasa magandang kondisyon',
    'landing.rights.habitability.pest': 'Kontrol ng peste na nagpapanatili sa gusali na naaayon-ayon na malaya mula sa rodents at insekto',
    'landing.rights.habitability.structure': 'Structural integrity na may palapag, dingdig, kisame, at hagdan sa magandang pagreparasyon',
    'landing.rights.habitability.nrs': 'NRS 118A.290 - Implikadong Garantiya ng Habitability',
    'landing.rights.retaliation.title': 'Proteksyon Laban sa Pagreretaliasyon',
    'landing.rights.retaliation.description': 'Ang mga landlord ay hindi makakasama sa iyo para sa pagsagamit ng iyong mga legal na karapatan. Ito ay ilegal para sa kanila na gumawa ng pagreretaliasyon laban sa iyo para sa:',
    'landing.rights.retaliation.organize': 'Pag-organisa o pagsali sa isang tenant union',
    'landing.rights.retaliation.report': 'Pagsasabing-daan ng mga paglalabas ng code sa mga agensiyang panggobyerno',
    'landing.rights.retaliation.union': 'Paglagay ng mga kaso o reklamo na nauugnay sa habitability',
    'landing.rights.retaliation.nrs': 'NRS 118A.510 - Proteksyon Laban sa Pagreretaliasyon. Ang mga lumalabas ay maaaring pilitin na magbayad ng $2,500 sa punitive damages plus actual damages.',
    'landing.rights.remedies.title': 'Ang Iyong Remedies Kapag Nabigo ang Mga Landlord',
    'landing.rights.remedies.intro': 'Kung ang iyong landlord ay lumalabas sa habitability warranty, mayroon kang legal remedies:',
    'landing.rights.remedies.essential.title': 'Para sa Mahalagang Serbisyo (init, tubig, kuryente, locks)',
    'landing.rights.remedies.essential.text': 'Magbigay ng nakasulat na abiso, maghintay ng 48 oras (hindi kasama ang weekends), pagkatapos ay maaari mong makuha ang serbisyo at ibawas ang aktwal na gastos mula sa renta, o ihawak ang renta hanggang sa matapos ang pagreparasyon.',
    'landing.rights.remedies.non_essential.title': 'Para sa Ibang Mga Isyung Habitability (peste, structural damage)',
    'landing.rights.remedies.non_essential.text': 'Magbigay ng nakasulat na abiso, maghintay ng 14 araw para sa landlord na magrepair o gumawa ng pinakamagandang pagsisikap, pagkatapos ay maaari mong iwalay ang lease, ihawak ang renta nang walang late fees, o para sa repairs sa ilalim ng $100, repair at ibawas.',
    'landing.rights.remedies.warning.title': 'Mahalaga para sa Rent Withholding:',
    'landing.rights.remedies.warning.text': 'Ang Nevada courts ay nangangailangan na mag-ipon ka ng witheld rent sa escrow ng court upang gamitin ang habitability bilang depensa sa pagsasakatawan. Kung walang ito, ikaw ay umiikot ng panganib na mawalan ng iyong kaso.',

    // Organizing Works Section
    'landing.organizing.title': 'Ang Pag-organize ay Gumagana—Ito ang Patunay',
    'landing.organizing.subtitle': 'Sa buong bansa, ang mga tenant na nagsama-sama ay nanalo sa konkretong pagpapabuti. Hindi ito mga napakailangang insidente kundi bahagi ng lumalaking pandaigdigang kilusan.',
    'landing.organizing.kc.title': 'KC Tenants Strike',
    'landing.organizing.kc.stat': '248 araw sa strike. $300,000 sa back rent na nakalimutan.',
    'landing.organizing.kc.win1': 'Rent freeze para sa lahat ng kasalukuyang tenant (pangalawang taon na limitado sa 5%)',
    'landing.organizing.kc.win2': 'Halos $300,000 sa witheld rent na nakalimutan—$0 back rent na may utang',
    'landing.organizing.kc.win3': 'Pormal na kinikilala ng unyon na may karapatang muling tukuyin taun-taon',
    'landing.organizing.kc.win4': 'Proteksyon laban sa pagreretaliasyon na naisulat sa kasunduan, reform ng late fee, komprehensibong garantiya ng pagreparasyon',
    'landing.organizing.ny.title': 'New York Good Cause Eviction',
    'landing.organizing.ny.stat': '~1 milyong mga tenant na protektado',
    'landing.organizing.ny.description': 'Pagkatapos ng limang taon ng patuloy na pag-organisa, ang New York ay pumasa ng proteksyon sa estado sa 2024.',
    'landing.organizing.ny.win1': 'Mga limitasyon ng pagtaas ng renta na walang matalinong dahilan sa 5% + CPI (o 10%, alin man ang mas mababa)',
    'landing.organizing.ny.win2': 'Nangangailangan na ang mga landlord ay may magandang dahilan upang magsasakatawan o tanggihan ang pagpapabago ng lease',
    'landing.organizing.ca.title': 'California AB 1482',
    'landing.organizing.ca.stat': '~8 milyong mga tenant na nakakuha ng proteksyon',
    'landing.organizing.ca.description': 'Ang Tenant Protection Act ng California (2019) ay naging modelo para sa proteksyon ng tenant sa buong bansa.',
    'landing.organizing.ca.win1': 'Limitasyon ng pagtaas ng renta sa estado na 5% + lokal na CPI (o maximum 10%)',
    'landing.organizing.ca.win2': 'Pangangailangan ng good cause eviction pagkatapos ng 12 buwan + isang buwan ng tulong sa muling paglalakbay',
    'landing.organizing.or.title': 'Oregon SB 608',
    'landing.organizing.or.stat': 'Una sa bansa rent control sa estadong antas',
    'landing.organizing.or.description': 'Ang Oregon ay naging unang estado upang pumasa ng state-level na rent control (2019).',
    'landing.organizing.or.win1': 'Taunang limitasyon ng pagtaas ng renta na 7% + CPI',
    'landing.organizing.or.win2': 'Proteksyon sa good cause eviction pagkatapos ng 12 buwan',
    'landing.organizing.message': 'Ang mga indibidwal na reklamo ay binalewala. Ang kolektibong aksyon ay nakakakuha ng mga resulta. Ang mga tagumpay na ito ay nagsasalita nito.',

    // Local Crisis Section
    'landing.crisis.title': 'Ang Housing Crisis sa Reno-Sparks',
    'landing.crisis.subtitle': 'Hindi ito mga abstract na problema—ito ang mga kondisyon na kinakaharap ng mga tenant sa Washoe County bawat buwan.',
    'landing.crisis.rent_increase': '40-45%',
    'landing.crisis.rent_increase_label': 'Pagtaas ng renta mula 2019',
    'landing.crisis.cost_burdened': 'Mga tenant na may cost-burden (nagbabayad ng 30%+ ng kita sa housing)',
    'landing.crisis.minimum_wage_hours': 'Minimum wage na oras bawat linggo na kailangan para sa 1-bedroom',
    'landing.crisis.homeless': 'Mga taong walang tahanan sa Washoe County (2024)',
    'landing.crisis.daily_evictions': 'Mga sakasakatawan na nailagay bawat araw (statewide)',
    'landing.crisis.luxury_units': 'Ng mga apartment na binuo sa Reno (nakaraang dekada) ay luxury units',
    'landing.crisis.impact': 'Ang renta ay tumaas ng 40-45% sa loob ng limang taon. Mahigit kalahati ng mga tenant ay may cost-burden. Ang isang minimum wage worker ay kailangang magtrabaho ng 82 oras bawat linggo upang magbayad ng one-bedroom apartment. Ang Nevada ay may pinakamabilis na proseso ng eviction sa bansa. Samantala, ang mga luxury apartment ay nakatuon habang 1,760 tao ay walang lugar na matulog.',
    'landing.crisis.support_title': 'May Suporta Kung Kailangan Mo',
    'landing.crisis.support_intro': 'Hindi ka nag-iisa. May legal aid, tulong sa emergency, at organizational support na available:',
    'landing.crisis.support_legal': 'Libreng legal na tulong para sa eviction defense at habitability issues',
    'landing.crisis.support_assistance': 'Tulong sa emergency rental at mga programa sa eviction diversion',
    'landing.crisis.support_advocacy': 'Mga organisasyong pang-tenant na lumalaban para sa pagbabago ng patakaran',

